#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{submitFeedbackStatus,jdbcType=VARCHAR}
and CHB_SUBMIT_DEADLINE between /*to_date(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'yyyy-mm-dd')*/ STR_TO_DATE(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'%Y-%m-%d')and/* to_date(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'yyyy-mm-dd')*/STR_TO_DATE(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'%Y-%m-%d')
and /* to_char(DATA_DATE,'yyyy-MM-dd')*/ DATE_FORMAT(DATA_DATE,'%Y-%m-%d')>= #{searchDataDateStart,jdbcType=VARCHAR}
and /*to_char(DATA_DATE,'yyyy-MM-dd')*/ DATE_FORMAT(DATA_DATE,'%Y-%m-%d')<= #{searchDataDateEnd,jdbcType=VARCHAR}
