mapper.insert:
insert into CHB_SALER_IDEN_SUB ( REGIST_SEQNO, SALER_INST_CODE,SALER_NAME,SALER_SEX,SALER_BIRTHDAY,SALER_CREDENT_TYPE, SALER_OTHER_CREDENT_NAME,SALER_CREDENT_NO,SALER_INS_NO,SALER_REGIST_NO, SALER_AREA_TYPE,SALER_ORG_CODE,SALER_DEPT,SALER_POSITION,SALER_EDU_LEVEL, SALER_DEGREE,SALER_WORK_START_YMD,SALER_FINANCE_START_YMD,SALER_START_YMD, SALER_LEVLE,SALER_CERTIFICATE_TYPE,SALER_CHB_TRAIN_NO,SALER_RISK_LEVEL, SALER_QUALIFICATION,SALER_TEL,SALER_MOBILE,SALER_MAIL,SALER_STATUS,REMARK, STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, DATA_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS, SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG,CREATE_DEPT,ORG_CODE, CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME) select HIS_NO, SALER_INST_CODE,SALER_NAME,SALER_SEX,SALER_BIRTHDAY,SALER_CREDENT_TYPE, SALER_OTHER_CREDENT_NAME,SALER_CREDENT_NO,SALER_INS_NO,SALER_REGIST_NO, SALER_AREA_TYPE,SALER_ORG_CODE,SALER_DEPT,SALER_POSITION,SALER_EDU_LEVEL, SALER_DEGREE,SALER_WORK_START_YMD,SALER_FINANCE_START_YMD,SALER_START_YMD, SALER_LEVLE,SALER_CERTIFICATE_TYPE,SALER_CHB_TRAIN_NO,SALER_RISK_LEVEL, SALER_QUALIFICATION,SALER_TEL,SALER_MOBILE,SALER_MAIL,SALER_STATUS,REMARK, STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, DATA_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS, SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG,CREATE_DEPT,ORG_CODE, CREATE_USER,his.CREATE_TIME,UPDATE_USER,UPDATE_TIME from CHB_SALER_IDEN_SUB_HIS his INNER join ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_SALER_IDEN_SUB_HIS
SALER_INS_NO IN
#{regist.salerInsNo,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME
SALER_INS_NO IN
#{regist.salerInsNo,jdbcType=VARCHAR}

mapper.delete:
delete from CHB_SALER_IDEN_SUB_HIS where CREATE_TIME=( SELECT T.CREATE_TIME FROM ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_SALER_IDEN_SUB_HIS
SALER_INS_NO IN
#{regist.salerInsNo,jdbcType=VARCHAR}
)T)
and SALER_INS_NO IN
#{regist.salerInsNo,jdbcType=VARCHAR}

